sparql:
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
#MANUAL SPARQL
PREFIX ns: <http://rdf.freebase.com/ns/>
SELECT DISTINCT ?x 
WHERE {
	{ 
	  ?c ns:location.country.administrative_divisions ?x .
	  ?x ns:common.topic.notable_types ns:m.02xhc47 .  #australian state
	}
	UNION
	{ 
	  ?c ns:location.country.administrative_divisions ?x .
	  ?x ns:common.topic.notable_types ns:m.02_8yfs .  #australian external territory
	}
	UNION
	{ 
	  ?c ns:location.country.administrative_divisions ?x .
	  ?x ns:common.topic.notable_types ns:m.02xhc4k .  #australian territory
	}
}

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
#MANUAL SPARQL
PREFIX ns: <http://rdf.freebase.com/ns/>
SELECT DISTINCT ?x
WHERE {
	{ 
	ns:m.0321b4 ns:film.film_character.portrayed_in_films ?y .
	?y ns:film.performance.actor ?x .
	}
	UNION
	{
	ns:m.0321b4 ns:tv.tv_character.appeared_in_tv_program ?y .
	?y ns:tv.regular_tv_appearance.actor ?x .
	}
}

